// Días a revisar según la agenda real (appointments-config): el pedido, o los próximos 4 hábiles para la agenda.
const cfg = ($json && $json.data) || {};
const t = $('Entrada').first().json;
const feriados = new Set(cfg.holidays || []);
const semana = cfg.weekSchedule || {};
const nombres = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const hoy = DateTime.now().setZone('America/Santiago').startOf('day');
const abre = d => { const s = semana[nombres[d.weekday % 7]]; return s && s.enabled ? s : null; };
const fin = msg => [{ json: { fin: true, result: msg } }];
const pedida = String(t.fecha || '').trim();
if (pedida) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(pedida)) return fin('Fecha inválida: usa el formato AAAA-MM-DD.');
  const d = DateTime.fromISO(pedida, { zone: 'America/Santiago' });
  if (!d.isValid) return fin('Fecha inválida.');
  if (d < hoy) return fin('Esa fecha ya pasó. Ofrece los próximos días disponibles.');
  if (d > hoy.plus({ days: 60 })) return fin('Solo agendamos hasta 60 días adelante.');
  if (feriados.has(pedida)) return fin('El ' + pedida + ' es feriado: no hay reuniones ese día. Ofrece otro día.');
  const s = abre(d);
  if (!s) return fin('Ese día no atendemos. Ofrece otro día.');
  return [{ json: { fin: false, date: pedida, start: s.start, end: s.end } }];
}
const out = [];
for (let i = 0; i < 21 && out.length < 4; i++) {
  const d = hoy.plus({ days: i });
  const iso = d.toISODate();
  const s = abre(d);
  if (s && !feriados.has(iso)) out.push({ json: { fin: false, date: iso, start: s.start, end: s.end } });
}
return out.length ? out : fin('No encontramos días disponibles en las próximas semanas.');

// Horas libres por día (en punto, con al menos 2 horas de anticipación). Hasta 3 días y 8 horas por día.
const fechas = $('Fechas a revisar').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const ahora = DateTime.now().setZone('America/Santiago');
const lineas = [];
res.forEach((r, i) => {
  const f = fechas[i];
  if (!f || lineas.length >= 3) return;
  const etiqueta = DateTime.fromISO(f.date, { zone: 'America/Santiago' }).setLocale('es').toFormat("cccc d 'de' LLLL") + ' (' + f.date + ')';
  const ini = parseInt(((r.workingHours || {}).start) || f.start, 10);
  const fin = parseInt(((r.workingHours || {}).end) || f.end, 10);
  const ocupadas = new Set((r.busySlots || []).map(x => String(x).slice(0, 5)));
  const libres = [];
  if (!r.isFullDay) {
    for (let h = ini; h < fin; h++) {
      const hh = String(h).padStart(2, '0') + ':00';
      if (ocupadas.has(hh)) continue;
      if (DateTime.fromISO(f.date + 'T' + hh, { zone: 'America/Santiago' }) < ahora.plus({ hours: 2 })) continue;
      libres.push(hh);
    }
  }
  if (libres.length) lineas.push('- ' + etiqueta + ': ' + libres.slice(0, 8).join(', '));
  else if (fechas.length === 1) lineas.push('- ' + etiqueta + ': sin horas libres. Ofrece otro día.');
});
const txt = lineas.length ? 'Horas libres (hora de Chile, reuniones de 1 hora):\n' + lineas.join('\n')
  : 'No hay horas libres en los próximos días. Ofrece derivar a una persona.';
return [{ json: { result: txt } }];

// Revisa la cita antes de agendar. El sub-workflow de PROD vuelve a revisar el horario en WordPress y en Calendar.
// Nombre, correo y WhatsApp con la validación común del Cerebro AT (N8N/cerebro-at/validacion.js, la mantiene Eje).
// <<VALIDACION AT: inicio>>
const AT_NO_NOMBRES = new Set(['hola', 'holi', 'ola', 'buenas', 'buenos', 'buena', 'dias', 'días', 'tardes', 'noches',
  'si', 'sí', 'no', 'ok', 'oka', 'okey', 'dale', 'claro', 'gracias', 'listo', 'perfecto', 'bueno', 'quiero', 'agendar',
  'agenda', 'cita', 'reunion', 'reunión', 'demo', 'diagnostico', 'diagnóstico', 'test', 'prueba', 'nombre', 'apellido',
  'correo', 'email', 'whatsapp', 'tech', 'bot']);

// Nombre y apellido: al menos dos palabras de dos letras o más, solo letras (con tildes, ñ, ü), guion o apóstrofo.
function atValidarNombre(texto) {
  const limpio = String(texto || '').replace(/\s+/g, ' ').trim();
  if (!limpio) return { ok: false, motivo: 'vacio' };
  if (limpio.length > 60) return { ok: false, motivo: 'largo' };
  if (/[0-9@]/.test(limpio)) return { ok: false, motivo: 'caracteres' };
  if (!/^[A-Za-zÁÉÍÓÚáéíóúÑñÜü' -]+$/.test(limpio)) return { ok: false, motivo: 'caracteres' };
  const palabras = limpio.split(' ').filter(p => p.replace(/['-]/g, '').length > 0);
  if (palabras.some(p => AT_NO_NOMBRES.has(p.toLowerCase()))) return { ok: false, motivo: 'no_es_nombre' };
  if (palabras.length < 2 || palabras.filter(p => p.replace(/['-]/g, '').length >= 2).length < 2) {
    return { ok: false, motivo: 'falta_apellido' };
  }
  const nombre = palabras.map(p => p.split('-').map(s => s ? s[0].toUpperCase() + s.slice(1).toLowerCase() : s).join('-')).join(' ');
  return { ok: true, valor: nombre };
}

// Errores de tipeo frecuentes en dominios de correo: se rechazan y se sugiere el correcto.
const AT_DOMINIOS_MAL = {
  'gmial.com': 'gmail.com', 'gmai.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gamil.com': 'gmail.com',
  'gmaill.com': 'gmail.com', 'gmail.co': 'gmail.com', 'gmail.con': 'gmail.com', 'gmail.cm': 'gmail.com',
  'gmail.om': 'gmail.com', 'gmail.cl': 'gmail.com', 'gmail.comm': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotamil.com': 'hotmail.com', 'hotmai.com': 'hotmail.com',
  'hotmail.con': 'hotmail.com', 'hotmail.co': 'hotmail.com', 'hotmail.cm': 'hotmail.com',
  'outlok.com': 'outlook.com', 'outllok.com': 'outlook.com', 'outlook.con': 'outlook.com', 'outlook.co': 'outlook.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'yahooo.com': 'yahoo.com',
  'iclod.com': 'icloud.com', 'icloud.con': 'icloud.com', 'iclud.com': 'icloud.com',
};

function atValidarCorreo(texto) {
  const correo = String(texto || '').trim().toLowerCase().replace(/^mailto:/, '');
  if (!correo) return { ok: false, motivo: 'vacio' };
  if (correo.length > 254 || /\s/.test(correo)) return { ok: false, motivo: 'formato' };
  const m = correo.match(/^([a-z0-9._%+-]+)@([a-z0-9-]+(?:\.[a-z0-9-]+)+)$/);
  if (!m) return { ok: false, motivo: 'formato' };
  const [, local, dominio] = m;
  if (/^\.|\.$|\.\./.test(local) || dominio.split('.').some(e => !e || /^-|-$/.test(e))) return { ok: false, motivo: 'formato' };
  if (!/\.[a-z]{2,}$/.test(dominio)) return { ok: false, motivo: 'formato' };
  const sugerido = AT_DOMINIOS_MAL[dominio] || (/\.(con|cmo|cpm|comm|vom)$/.test(dominio) ? dominio.replace(/\.[a-z]+$/, '.com') : '');
  if (sugerido) return { ok: false, motivo: 'tipeo', sugerencia: local + '@' + sugerido };
  return { ok: true, valor: correo };
}

// WhatsApp con código de país, en formato +<código><número>. Un celular chileno sin código se completa con +56.
// En Chile el celular es +56 9 y ocho dígitos.
function atValidarWhatsApp(texto) {
  let tel = String(texto || '').replace(/[^\d+]/g, '');
  if (/^00\d/.test(tel)) tel = '+' + tel.slice(2);
  if (/^9\d{8}$/.test(tel)) tel = '+56' + tel;
  else if (/^569\d{8}$/.test(tel)) tel = '+' + tel;
  else if (/^\d{8,15}$/.test(tel) && !tel.startsWith('0')) tel = '+' + tel;
  if (!/^\+[1-9]\d{7,14}$/.test(tel)) return { ok: false, motivo: 'formato' };
  if (tel.startsWith('+56') && !/^\+569\d{8}$/.test(tel)) return { ok: false, motivo: 'chile' };
  return { ok: true, valor: tel };
}
// <<VALIDACION AT: fin>>
const t = $('Entrada').first().json;
const fecha = String(t.fecha || '').trim();
const hora = String(t.hora || '').trim().slice(0, 5);
const malo = msg => [{ json: { ok: false, result: msg + ' No agendes hasta tenerlo bien.' } }];
// Se juntan todos los datos malos para que el agente los pida en un solo mensaje.
const errores = [];
const vn = atValidarNombre(t.nombre);
if (!vn.ok) errores.push(vn.motivo === 'vacio' || vn.motivo === 'falta_apellido'
  ? 'Falta el nombre y apellido de la persona: pídeselo (si dio solo el nombre, pide el apellido).'
  : 'Eso no parece un nombre y apellido: pídeselo de nuevo.');
const vc = atValidarCorreo(t.correo);
if (!vc.ok) errores.push(vc.motivo === 'tipeo'
  ? 'El correo parece mal escrito: pregúntale si es ' + vc.sugerencia + '.'
  : 'El correo no es válido: pídeselo de nuevo.');
// Obligatorio desde el 28-oct (Luis): sin WhatsApp con código de país no se agenda.
const vw = atValidarWhatsApp(t.telefono);
if (!vw.ok) errores.push(vw.motivo === 'chile'
  ? 'El celular de Chile tiene que ser +56 9 y ocho dígitos (por ejemplo +56 9 1234 5678): pídeselo de nuevo.'
  : 'Falta el WhatsApp con código de país (es obligatorio): pídeselo con el ejemplo «en Chile: +56 9 1234 5678».');
if (errores.length) return malo((errores.length > 1 ? 'Pídele todo esto en un solo mensaje: ' : '') + errores.join(' '));
const nombre = vn.valor, correo = vc.valor, tel = vw.valor;
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !/^\d{2}:00$/.test(hora)) return malo('Fecha u hora inválida: fecha AAAA-MM-DD y hora en punto (HH:00).');
const dt = DateTime.fromISO(fecha + 'T' + hora, { zone: 'America/Santiago' });
if (!dt.isValid) return malo('Fecha u hora inválida.');
if (dt < DateTime.now().setZone('America/Santiago').plus({ hours: 2 })) return malo('Esa hora ya pasó o es muy pronto: ofrece otra con ver_disponibilidad.');
return [{ json: { ok: true, prueba: t.prueba === 'si', date: fecha, time: hora, email: correo, name: nombre, phone: tel,
  session_id: 'ig:' + String(t.igsid || ''), appointmentType: 'Demo' } }];

// Guarda firme (propuesta de Eje, 28-oct): solo se agenda una fecha que esta conversación consultó con ver_disponibilidad
// en las últimas 3 horas (Redis ig:disp:<IGSID>, la anota «Anotar fechas consultadas»).
const cita = $('Validar cita').first().json;
let fechas = [];
try { const v = JSON.parse(String($json.disp || '[]')); if (Array.isArray(v)) fechas = v; } catch (e) {}
if (!fechas.includes(cita.date)) {
  return [{ json: { ok: false, result: 'Antes de agendar consulta ver_disponibilidad para ' + cita.date
    + ' y confirma la hora con la persona. No agendes todavía.' } }];
}
return [{ json: cita }];
